-- ScholarBridgeAi — Scholarship rewrite pass 42 (Nordic tail: Finland, Denmark, Sweden)
-- Verified 2026-10-25 against the providers' own pages (cited in source_url).
-- The Nordic pattern is consistent and it is the opposite of what the old rows implied: non-EU
-- students pay tuition of EUR 13,000-18,000 or SEK 90,000-140,000 a year, and the scholarships are
-- tuition waivers that deliberately exclude living costs. Every one of the four rows mispriced that.
-- Values are in EUR or SEK; amount_usd_value stays 0 for non-USD awards.

-- 742 University of Helsinki
UPDATE scholarships SET
  title = 'University of Helsinki Scholarship Programme (Tuition Fee Waivers)',
  description = 'Helsinki is blunt about the shape of its support and the old record got the direction of it wrong. The University of Helsinki scholarship programme consists of tuition fee waivers worth either 50 per cent or 100 per cent of the fee, and the university states twice on its own page that only a very limited number of waivers can be awarded and that most of them cover 50 per cent. The fees themselves are published: EUR 13,000, 15,000 or 18,000 a year depending on the master''s programme, fixed for the duration of the student''s studies. A waiver runs for two years, and the student must earn at least 55 ECTS a year to keep it, with progress checked after the first year. The sentence that matters most is the one the old record ignored: the University of Helsinki does not offer scholarships to cover living expenses, so a student holding a 100 per cent waiver still has to fund roughly a year of Helsinki living costs from somewhere else. Applying costs nothing extra in effort but does cost money: the waiver is requested on the same Studyinfo form as the master''s application, during the January application window, and non-EU applicants pay a EUR 100 application fee. The decision arrives in the acceptance email rather than in a separate letter. A separate Finland Scholarship, worth a 100 per cent first-year waiver plus a EUR 5,000 relocation grant, is described by some national sources; Helsinki''s own scholarship page lists only the 50 and 100 per cent waivers and states that it does not fund living costs, so the relocation grant should be confirmed for the specific programme before it is counted.',
  requirements = 'Be liable for tuition fees, which means citizenship of a country outside the EU and EEA without permanent residence status in Finland. Be eligible for and apply to an English-taught master''s programme at the University of Helsinki during the January application window, using the Studyinfo portal and paying the EUR 100 application fee that applies to non-EU applicants. Request the tuition fee waiver on the same application form, choosing either the 50 per cent or the 100 per cent category. Meet the requirements for a Finnish entry visa and residence permit. Demonstrate strong previous academic performance, since waivers are awarded on an overall academic assessment that includes previous results, the motivation letter and the grounds given in the scholarship application. Once enrolled, complete at least 55 ECTS a year and study full time, because progress is checked after the first year and the waiver continues only if that condition is met.',
  coverage_type = 'Tuition Waiver', award_basis = 'range', award_amount = 18000, award_currency = 'EUR', award_period = 'year',
  degree_levels = '["Master''s"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Merit-based tuition fee waiver',
  tuition_coverage = 'A 50 per cent or 100 per cent waiver of a tuition fee of EUR 13,000, 15,000 or 18,000 a year, for two years, subject to earning at least 55 ECTS a year. Helsinki states that most waivers are 50 per cent and that it does not offer scholarships covering living expenses.',
  english_requirements = 'The waiver sets no separate English score; the English requirement of the chosen master programme applies.',
  required_documents = '["Master''s application through Studyinfo during the January window","Bachelor degree certificate and transcripts","Motivation letter that also supports the scholarship request","Proof of English proficiency as the programme requires","EUR 100 application fee payment for non-EU applicants","Scholarship request marked on the same application form"]',
  deadline = 'The January application window; for the 2026 intake Helsinki opened it from 2 to 16 January 2026, and the following cycle runs in the same period',
  deadline_date = NULL, deadline_type = 'annual', application_status = 'closed',
  expected_deadline_period = 'Helsinki opens its international master admissions and the scholarship request together in the first half of January each year for the August intake.',
  website_url = 'https://www.helsinki.fi/en/admissions-and-education/apply-bachelors-and-masters-programmes/tuition-fees-and-scholarship-programme',
  source_url = 'https://www.helsinki.fi/en/admissions-and-education/apply-bachelors-and-masters-programmes/tuition-fees-and-scholarship-programme',
  application_url = 'https://www.studyinfo.fi/',
  verification_status = 'verified', source_reliability = 9, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from the University of Helsinki tuition fees and scholarship programme page read on 2026-10-25, which states that the scholarship programme consists of tuition fee waivers waiving the fee by either 50 per cent or 100 per cent, that only a very limited number of waivers can be awarded and that most of them cover 50 per cent of the fee, that tuition fees range from EUR 13,000 to 18,000 and are fixed for the individual student throughout the programme, that the duration of the scholarship is two years, that students must earn at least 55 ECTS a year and that progress is checked after the first year, that the university does not offer scholarships to cover living expenses, that eligibility requires being liable for tuition fees as a non-EU or EEA citizen without permanent residence status in Finland, that the waiver is applied for with the master application and that the result arrives in the acceptance email. The national Finland Scholarship, described by third-party sources as a 100 per cent first-year waiver plus a EUR 5,000 relocation grant, is mentioned in the description with the caveat that Helsinki own page lists only the 50 and 100 per cent waivers. CORRECTIONS: the row was titled University of Helsinki Scholarship, carried an invented USD 14,000, claimed all three degree levels and gave a January deadline without saying what the award was. The real award is a tuition waiver of 50 or 100 per cent, master level only, explicitly excluding living costs, and the majority of recipients get 50 per cent rather than the full fee. award_amount carries the highest published fee, EUR 18,000, since a 100 per cent waiver is worth exactly that on the most expensive programmes.'
WHERE id = 742;

-- 733 University of Copenhagen
UPDATE scholarships SET
  title = 'University of Copenhagen Danish Government Scholarship',
  description = 'Copenhagen runs the Danish Government Scholarship and the mechanics are unusually favourable: there is no separate application at all, because every non-EU, EEA or Swiss applicant offered admission to a master''s programme is automatically considered. The award is decided purely on academic achievement - the university states that financial need is not taken into consideration - and it takes one of two forms, either a full or partial tuition waiver, or a waiver plus an amount covering basic living expenses. That distinction is worth understanding before applying. At the Faculty of Humanities the scholarship covers tuition plus living expenses for 22 months, but only applicants with a grade point average above 90 per cent of their bachelor''s are considered at all, only for a first-priority application, and in 2025 the recipients had a minimum GPA of 98 per cent. The Faculty of Science sets the threshold lower at above 85 per cent, awards a very limited number, and grants tuition only except in exceptional cases where living costs are added. Two warnings are published and both cost money. A living-expense grant is taxable under Danish law unless the recipient''s nationality is exempt, and some nationalities are. And the scholarship decision is generally made after admission and after the tuition invoice has been issued in mid-May, so a student cannot rely on the waiver when deciding whether to accept the place - if the tuition payment date is missed the offer is revoked. For September 2027 entry the deadline is 15 January 2027, with the portal opening on 15 November 2026 and replies by 13 March 2027.',
  requirements = 'Be a citizen of a country outside the EU, the EEA and Switzerland. Be admitted to a master''s degree programme at the University of Copenhagen, which for the humanities and science faculties means making that programme your first-priority application, since only first-priority applicants are considered. Submit the master''s application by 15 January 2027 for September 2027 entry, with the portal opening on 15 November 2026, and pay the Danish application fee. Hold or be granted a time-limited residence permit for the purpose of studying in Denmark. Meet the faculty grade threshold: above 90 per cent of the bachelor average at the Faculty of Humanities, where 2025 recipients had at least 98 per cent, and above 85 per cent at the Faculty of Science. No separate scholarship application is filed, since all eligible applicants offered admission are considered automatically, but be prepared to pay the tuition invoice by the mid-May date in the terms email because the scholarship decision comes afterwards.',
  coverage_type = 'Partial Funding', award_basis = 'variable', award_amount = NULL, award_currency = 'DKK', award_period = 'year',
  degree_levels = '["Master''s"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Government scholarship, awarded by the university',
  tuition_coverage = 'A full or partial tuition waiver, and in some cases a waiver plus a monthly amount for basic living costs. At the Faculty of Humanities it covers tuition and living expenses for 22 months; at the Faculty of Science it usually covers tuition only, with living costs added only in exceptional cases. No amount is published centrally because each faculty sets its own awards.',
  english_requirements = 'The scholarship sets no separate English score; the English requirement of the chosen master programme applies.',
  required_documents = '["Master''s application through the University of Copenhagen portal by 15 January","Bachelor degree certificate and transcripts showing the grade point average","English proficiency evidence as the programme requires","Danish application fee payment","Residence permit documentation","No separate scholarship application"]',
  deadline = '15 January 2027 for September 2027 entry; the portal opens on 15 November 2026 and replies are due by 13 March 2027',
  deadline_date = '2027-01-15', deadline_type = 'fixed', application_status = 'upcoming',
  website_url = 'https://www.ku.dk/studies/masters/application-and-admission/scholarships',
  source_url = 'https://www.ku.dk/studies/masters/application-and-admission/scholarships',
  application_url = 'https://www.ku.dk/studies/masters/application-and-admission/tuition-fees-and-scholarships',
  verification_status = 'verified', source_reliability = 9, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from two University of Copenhagen own pages read on 2026-10-25: the scholarships page states that the university offers a limited number of tuition waivers and grants through the Danish Government Scholarship programme, that all non-EU, EEA and Swiss applicants offered admission are automatically considered and no individual application is submitted, that eligibility requires citizenship outside the EU, EEA and Switzerland, admission to a master programme at the university and a time-limited residence permit for study, that the awards are decided solely on academic achievement with financial need not considered, that the scholarship either covers both tuition fees and living expenses or covers the tuition fee only, that living-expense grants are taxed under Danish law with some nationalities exempt and the award letter stating whether they are, that at the Faculty of Humanities the scholarship covers tuition and living expenses for 22 months, that only applicants with a grade point average above 90 per cent of their bachelor degree are considered and only on their first-priority application, that in 2025 recipients had a minimum grade point average of 98 per cent, and that decisions are generally made after admission and after the tuition invoice is issued in mid-May so the student cannot rely on the waiver when accepting a place; the tuition fees and scholarships page confirms the tuition liability rules, repeats the automatic consideration rule, gives the Faculty of Science threshold of above 85 per cent with a very limited number of awards usually covering tuition only and living expenses only in exceptional cases, and lists the exemptions. The 15 January 2027 deadline, the 15 November 2026 portal opening and the 13 March 2027 reply date come from the university deadlines page as reproduced in the funding guidance read the same day. CORRECTIONS: the row was titled University of Copenhagen (limited faculty-specific), carried an invented USD 15,000, claimed all three degree levels and gave a 15 March deadline. The real instrument is the Danish Government Scholarship, it is master level only, there is no separate application, the deadline is 15 January, the faculty GPA thresholds decide whether an applicant is looked at at all, and a living grant is taxable. award_amount is NULL because no central figure is published and the award may be a partial or a full waiver.'
WHERE id = 733;

-- 673 Stockholm University
UPDATE scholarships SET
  title = 'Stockholm University Scholarship Scheme',
  description = 'Stockholm University pays the whole tuition fee and nothing else, which makes it one of the cleaner offers in this cluster but also one of the easiest to misread. The Stockholm University Scholarship Scheme covers the entire tuition fee for a master''s programme, and the university states explicitly that students will need to cover their living costs themselves. The fees it waives are published per field: SEK 90,000 a year in the humanities, social sciences and law, and SEK 140,000 a year in the sciences, with some programmes priced inside that range and a few joint programmes above it. What makes this scheme unusual is the timing: there is no advance application. Eligible applicants are emailed a scholarship form once the admission results are published in April, and it goes to non-EU, EEA and Swiss citizens admitted in the first admissions round, assessed on academic merit, with priority to those who ranked Stockholm University first. Renewal into a second year is conditional on satisfactory progress. The application itself runs from 16 October to 15 January, with documents and the SEK 900 application fee due by 1 February, which means the student has to be ready to accept a place and pay a first instalment before the scholarship answer is final. Two related schemes are narrower: the Stockholm Trio Scholarship covers full tuition but only for two named programmes through KTH''s application, and the Swedish Institute Scholarship for Global Professionals is a full award with a monthly stipend but is limited to citizens of a specific list of countries that should be checked against Uzbekistan before planning around it.',
  requirements = 'Be a citizen of a country outside the EU, the EEA and Switzerland and therefore liable for tuition fees, and apply to a master''s programme at Stockholm University in the first admissions round between 16 October and 15 January, paying the SEK 900 application fee and uploading documents by 1 February. Rank Stockholm University first on your application, since priority is given to applicants who did so. Be admitted in the first round on academic merit, because the scheme has no advance application and the form is emailed to eligible applicants after the results are published in April. Hold the finances for living costs independently, since the scheme covers tuition only and the university states this plainly. To keep the waiver into the second year, make satisfactory academic progress. Note that the university offers no scholarships to EU, EEA or Swiss citizens, and that the Swedish Institute Scholarship for Global Professionals is restricted to a published list of countries.',
  coverage_type = 'Tuition Waiver', award_basis = 'fixed', award_amount = 140000, award_currency = 'SEK', award_period = 'year',
  degree_levels = '["Master''s"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Merit-based tuition fee waiver',
  tuition_coverage = 'The whole tuition fee for a master programme: SEK 90,000 a year in the humanities, social sciences and law and SEK 140,000 a year in the sciences, with some programmes priced inside that range and joint programmes above it. Living costs are explicitly not covered.',
  english_requirements = 'The scholarship sets no separate English score; the English requirement of the chosen master programme applies.',
  required_documents = '["Master application through universityadmissions.se between 16 October and 15 January","Documents uploaded and SEK 900 fee paid by 1 February","Bachelor degree certificate and transcripts","English proficiency evidence as the programme requires","Scholarship form returned after the April results","Proof of funds for living costs"]',
  deadline = 'Apply from 16 October to 15 January, with documents and the SEK 900 fee due by 1 February; the scholarship form follows the April results',
  deadline_date = NULL, deadline_type = 'annual', application_status = 'upcoming',
  expected_deadline_period = 'Applications open on 16 October each year and close on 15 January, results come in early April, and the scholarship form is emailed straight after the results.',
  website_url = 'https://www.su.se/english/education/how-to-apply/costs-fees-and-scholarships/scholarships',
  source_url = 'https://www.su.se/english/education/how-to-apply/costs-fees-and-scholarships/scholarships',
  application_url = 'https://www.universityadmissions.se/',
  verification_status = 'verified', source_reliability = 9, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from two Stockholm University own pages read on 2026-10-25: the scholarships page states that the Stockholm University Scholarship Scheme is aimed at especially qualified students and covers the whole tuition fee for a master programme at the university, so that students will need to cover their living costs; the costs, fees and scholarships page states that citizens of countries outside the EU, EEA and Switzerland are required to pay application and tuition fees, that the application fee is SEK 900 and that tuition is SEK 90,000 a year in the humanities, social sciences and law and SEK 140,000 a year in the sciences with some programmes priced in between and joint programmes higher; the pre-departure and payment pages confirm that the scheme is a tuition fee waiver for specially qualified master students, that there are no scholarships for EU, EEA or Swiss citizens, and that where the scheme is granted the tuition fee is repaid in full with a SEK 5,000 repayment fee applying to payments that are repaid; the application timeline reproduced in the university funding guidance gives 16 October 2026 for applications opening, 15 January 2027 for the application and ranking deadline and 1 February 2027 for documents and fee, with results in early April and the scholarship form emailed after results. CORRECTIONS: the row was titled Stockholm University Scholarship, carried an invented USD 12,000, claimed all three degree levels and gave a 15 January deadline as if the scholarship were applied for then. The real scheme is master level only, it covers tuition and never living costs, there is no advance application because the form arrives after the April results, and the value depends on the field at SEK 90,000 or 140,000 a year. award_amount carries the higher published annual fee of SEK 140,000, which is what a full waiver is worth on a science programme.'
WHERE id = 673;

-- 739 University of Gothenburg
UPDATE scholarships SET
  title = 'Axel Adler Scholarship (University of Gothenburg)',
  description = 'Gothenburg''s main scholarship is the Axel Adler Scholarship, and its most useful feature for an applicant from Uzbekistan is the one the old record buried: the university states that it has no restrictions on citizenship, making it open to students worldwide. It is a tuition fee waiver rather than a cash award, and the university is direct that it does not provide financial support for living expenses or travel. The allocation is granular - one scholarship is awarded for each master''s programme and each eligible bachelor''s programme, four in total across the Artistic Faculty, and up to ten additional scholarships if funds allow - which means the odds depend heavily on which programme you choose. Selection is on the CV and letter of motivation submitted with the scholarship application, plus academic merits. The award is funded by the Adlerbertska Scholarship Foundation, the Adlerbertska Grant Foundation and the Swedish Council for Higher Education, and the foundations pay the tuition fee directly to the university, so the student does not pay it and then claim it back. Two conditions matter: the applicant must have chosen Gothenburg as their first-choice university on universityadmissions.se, and the award cannot be combined with another scholarship that covers tuition, so a student who wins both this and something else must give one up. A parallel scheme for the School of Business, Economics and Law, the Richard C. Malmsten Memorial Foundation Scholarship, waives SEK 100,000 over two years, which is SEK 25,000 a semester, but requires a GMAT score and is not available to students who already hold a Swedish Institute or Gothenburg study scholarship.',
  requirements = 'Have applied for an international bachelor''s or master''s programme at the University of Gothenburg and be required to pay tuition fees, which means non-EU, EEA or Swiss citizenship. Choose the University of Gothenburg as your first-choice university on universityadmissions.se, since the scholarship is aimed at students who do so. Submit the scholarship application with a CV and a letter of motivation, which are what the academic staff assess and rank, alongside academic merits. Be admitted to a campus-based programme in Gothenburg, since online programmes are excluded. Hold the funds for living costs and travel separately, because the award covers tuition only. Accept that the scholarship cannot be combined with another tuition-covering scholarship, so only one can be held. For the School of Business, Economics and Law alternative, hold a GMAT score and apply to the Richard C. Malmsten Memorial Foundation Scholarship, which is unavailable to holders of a Swedish Institute or Gothenburg study scholarship.',
  coverage_type = 'Tuition Waiver', award_basis = 'variable', award_amount = NULL, award_currency = 'SEK', award_period = 'year',
  degree_levels = '["Bachelor''s","Master''s"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Tuition fee waiver funded by foundations',
  tuition_coverage = 'A waiver of the programme tuition fee, paid directly by the foundations to the university. Living costs and travel are explicitly not covered. One scholarship per master''s programme and per eligible bachelor''s programme, four across the Artistic Faculty, plus up to ten additional awards if funds allow.',
  english_requirements = 'The scholarship sets no separate English score; the English requirement of the chosen programme applies.',
  required_documents = '["Programme application through universityadmissions.se with Gothenburg ranked first","Scholarship application with CV and letter of motivation","Bachelor degree certificate and transcripts where required","English proficiency evidence as the programme requires","Proof of funds for living costs","GMAT score for the School of Business, Economics and Law scholarship"]',
  deadline = 'The scholarship application follows the national admission round, which closes on 15 January for the autumn intake; the tuition fee is due by 1 May if no scholarship is awarded',
  deadline_date = NULL, deadline_type = 'annual', application_status = 'open',
  expected_deadline_period = 'Gothenburg opens scholarship applications alongside the national admission round in the autumn and closes them in mid-January for the autumn intake.',
  website_url = 'https://www.gu.se/en/study-in-gothenburg/apply/scholarships-for-fee-paying-students/axel-adler-scholarship',
  source_url = 'https://www.gu.se/en/study-in-gothenburg/apply/scholarships-for-fee-paying-students/axel-adler-scholarship',
  application_url = 'https://www.gu.se/en/study-in-gothenburg/apply/scholarships-for-fee-paying-students',
  verification_status = 'verified', source_reliability = 9, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from three University of Gothenburg own pages read on 2026-10-25: the Axel Adler Scholarship page states that applicants for an international bachelor or master programme who are required to pay tuition fees may be eligible, that the scholarship is a tuition fee waiver with selection primarily based on qualifications for the programme, that it is funded by the Adlerbertska Scholarship Foundation, the Adlerbertska Grant Foundation and the Swedish Council for Higher Education, that academic staff assess and rank applications on the CV and letter of motivation with academic merits also taken into account, that one scholarship is awarded for each master programme and each eligible bachelor programme with four in total across the Artistic Faculty and up to ten additional if funds allow, that it covers the tuition fee and does not provide financial support for living expenses or travel, that online programmes are excluded, that it cannot be combined with another tuition-covering scholarship, and that the foundations pay the tuition fee directly to the university; the school of business page states that the Richard C. Malmsten Memorial Foundation Scholarship covers SEK 100,000 over two years as a waiver of SEK 25,000 per semester, that students without a GMAT score will not be considered, and that holders of Swedish Institute or Gothenburg study scholarships are excluded; the university news page states that the Axel Adler Scholarship has no restrictions on citizenship, making it accessible to students worldwide, that 112 students are currently funded and that the university aimed to award 70 to 80 new scholarships for 2024 admission; the tuition fees page states that the tuition fee is due by 1 May if no scholarship is awarded and that the university handles the fee itself once a scholarship is registered. CORRECTIONS: the row was titled University of Gothenburg Study Scholarships, carried an invented USD 12,500, claimed all three degree levels and gave a 15 January deadline as if it were a scholarship date. The real instrument is the Axel Adler Scholarship, it is a tuition-only waiver, the number of awards is set per programme rather than overall, and the citizenship point is the opposite of what most Swedish schemes imply - it is open to all nationalities. award_amount is NULL because the value depends on the programme fee and the university publishes the fee per programme rather than a scholarship figure.'
WHERE id = 739;

-- university_scholarships cards
UPDATE university_scholarships u SET scholarship_name = v.name, availability_status = 'Yes', funding_type = v.ftype, max_scholarship = v.mx, covers_tuition = true, covers_living_expenses = v.living, eligibility_notes = v.elig, official_url = v.url, source_url = v.url, verification_status = 'verified', last_verified_at = now()
FROM (VALUES
  (182, 'University of Helsinki Scholarship Programme (Tuition Fee Waivers)', 'Merit-based tuition fee waiver', 'A 50% or 100% waiver of a EUR 13,000-18,000 annual fee', true, false, 'Master level only. Helsinki states that only a very limited number of waivers exist and most cover 50%. Two-year duration, at least 55 ECTS a year. Living costs are explicitly not funded. Requested on the same Studyinfo form as the master application in the January window, with a EUR 100 application fee for non-EU applicants.', 'https://www.helsinki.fi/en/admissions-and-education/apply-bachelors-and-masters-programmes/tuition-fees-and-scholarship-programme'),
  (181, 'University of Copenhagen Danish Government Scholarship', 'Government scholarship awarded by the university', 'Full or partial tuition waiver, sometimes plus a living grant', true, true, 'Every non-EU/EEA applicant offered admission is considered automatically; no separate application. Faculty thresholds apply: above 90% GPA at Humanities, where 2025 recipients had at least 98%, and above 85% at Science. Living grants are taxed. Decisions come after the mid-May tuition invoice, so the waiver cannot be relied on when accepting. Deadline 15 January 2027.', 'https://www.ku.dk/studies/masters/application-and-admission/scholarships'),
  (134, 'Stockholm University Scholarship Scheme', 'Merit-based tuition fee waiver', 'The whole tuition fee: SEK 90,000 or 140,000 a year depending on field', true, false, 'Master level only and open only to non-EU/EEA/Swiss citizens admitted in the first round, with priority for those who ranked Stockholm first. There is no advance application: the form is emailed after the April results. Living costs are not covered. Applications run 16 October to 15 January with documents and the SEK 900 fee by 1 February.', 'https://www.su.se/english/education/how-to-apply/costs-fees-and-scholarships/scholarships'),
  (130, 'Axel Adler Scholarship (University of Gothenburg)', 'Tuition fee waiver funded by foundations', 'A waiver of the programme tuition fee, paid directly by the foundations', true, false, 'Open to all nationalities with no citizenship restriction, for fee-paying students who rank Gothenburg first on universityadmissions.se. One award per master programme and per eligible bachelor programme, four across the Artistic Faculty, plus up to ten more if funds allow. Covers tuition only and cannot be combined with another tuition scholarship.', 'https://www.gu.se/en/study-in-gothenburg/apply/scholarships-for-fee-paying-students/axel-adler-scholarship')
) AS v(id, name, ftype, mx, living, elig, url)
WHERE u.id = v.id;
